args.command:
kubectl run node-shell --restart=Never --image=busybox --overrides='
{
  "spec": {
    "hostPID": true,
    "hostNetwork": true,
    "tolerations": [
      {
        "operator": "Exists"
      }
    ],
    "containers": [
      {
        "name": "shell",
        "image": "busybox",
        "command": ["chroot", "/host", "sh", "-c", "kubeadm version; crictl version; which kubeadm kubelet containerd"],
        "securityContext": {
          "privileged": true
        },
        "volumeMounts": [
          {
            "name": "host-root",
            "mountPath": "/host"
          }
        ]
      }
    ],
    "volumes": [
      {
        "name": "host-root",
        "hostPath": {
          "path": "/"
        }
      }
    ]
  }
}'
